    return {"ok": True}

def handle_import(connection, payload):
    if not isinstance(payload, dict) or set(payload.keys()) != {"contacts"} or not isinstance(payload["contacts"], list):
        raise ValueError("payload must be an object with a contacts list")
    return import_contacts(connection, payload["contacts"])

